@startuml

class InsuranceCompany {}

class PolicyType {
  + TypeName : string
}

class Policy {
  + PolicyId : string
  + CoverageDetails : string
}

class Customer {
  + CustomerId : int
  + Name : string
  + ContactInfo : string
}

class Contract {
  + ContractId : int
  + SigningDate : date
  + Status : string
}

InsuranceCompany "1" -- "1..*" Policy
InsuranceCompany "1" -- "1..*" Customer
Customer "1" -- "0..*" Contract
Contract "0..*" -- "1" Policy
Policy "1" -- "1" PolicyType

@enduml

